<?php
namespace App\Models;
use App\Models\Concerns\BelongsToOrganization; use App\Models\Concerns\HasBusinessNumber; use Illuminate\Database\Eloquent\Attributes\Fillable; use Illuminate\Database\Eloquent\Concerns\HasUlids; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
#[Fillable(['document_name','original_filename','stored_filename','document_type','category','mime_type','extension','file_size','storage_disk','storage_path','checksum','version','visibility','status','expires_at','uploaded_by'])]
class Document extends Model { use BelongsToOrganization,HasUlids,HasBusinessNumber,SoftDeletes; public static function businessCode():string{return 'DOC';} public function businessNumberColumn():string{return 'document_number';} protected function casts():array{return ['file_size'=>'integer','version'=>'integer','expires_at'=>'date'];} public function relations(){return $this->hasMany(DocumentRelation::class);} public function versions(){return $this->hasMany(DocumentVersion::class);} public function verifications(){return $this->hasMany(DocumentVerification::class);} public function accessLogs(){return $this->hasMany(DocumentAccessLog::class);} }
